const rawInput = $input.first().json;
const body = rawInput.body ? rawInput.body : rawInput;

if (!body.request_id) {
  return [{ json: { decision: 'REJECTED', reason: 'MISSING_REQUEST_ID', message: 'request_id is required.' } }];
}

// confirmed_* fields are optional - present only on the second call to
// this webhook, once the seller has reviewed (and possibly edited) the
// generated parent content at Approval. Their absence is the normal,
// expected shape of the first call, not an error.
return [{ json: {
  decision: 'VALID',
  request_id: body.request_id,
  confirmed_title: body.confirmed_title || null,
  confirmed_bullet_points: Array.isArray(body.confirmed_bullet_points) ? body.confirmed_bullet_points : null,
  confirmed_description: body.confirmed_description || null
} }];

const merge = $('Fetch Merge Request').first().json;
const mergeRow = Array.isArray(merge) ? merge[0] : merge;

if (!mergeRow) {
  return [{ json: {
    decision: 'REJECTED',
    reason: 'MERGE_REQUEST_NOT_FOUND',
    message: 'No merge_requests row found for this request_id.'
  }}];
}

// Hoisted up from further down this function so the productType fix
// below (right after the anchor fetch) can use it too.
const mkId = mergeRow.marketplace_id;

if (!mergeRow.anchor_sku) {
  return [{ json: {
    decision: 'REJECTED',
    reason: 'MISSING_ANCHOR_SKU',
    request_id: mergeRow.request_id,
    message: 'This merge request has no anchor_sku stored - cannot build a new parent without knowing which listing to copy required content from.'
  }}];
}

if (!mergeRow.new_parent_sku) {
  return [{ json: {
    decision: 'REJECTED',
    reason: 'MISSING_NEW_PARENT_SKU',
    request_id: mergeRow.request_id,
    message: 'This merge request has no new_parent_sku stored - the seller has not yet chosen a SKU for the brand-new parent record.'
  }}];
}

const itemsInput = $('Fetch Items').all();
let items;
if (itemsInput.length === 1 && Array.isArray(itemsInput[0].json)) {
  items = itemsInput[0].json;
} else {
  items = itemsInput.map(function(i) { return i.json; });
}

const missingParentSku = items.filter(function(i) { return !i.parent_sku; });
if (missingParentSku.length > 0) {
  return [{ json: {
    decision: 'REJECTED',
    reason: 'MISSING_PARENT_SKU',
    request_id: mergeRow.request_id,
    message: 'One or more children have no parent_sku stored (should reference the new parent SKU). Cannot build a real feed without it.',
    affected_skus: missingParentSku.map(function(i) { return i.sku; })
  }}];
}

const anchorItem = $('Fetch Anchor Listing').first().json;
if (!anchorItem || anchorItem.errors) {
  return [{ json: {
    decision: 'REJECTED',
    reason: 'ANCHOR_FETCH_FAILED',
    request_id: mergeRow.request_id,
    message: 'Could not fetch the anchor listing\'s own attributes from Amazon.',
    upstream_raw: anchorItem
  }}];
}

// Two-call design: first call (no confirmed_* fields) generates draft
// title/bullets/description and stops here so the seller can review them
// at Approval; second call, with the seller's confirmed (possibly
// edited) values, continues on past this point to actually build the
// submission payload. See "Generate Generic Parent Content" for the
// generation logic itself.
const contentResult = $('Generate Generic Parent Content').first().json;
if (contentResult.decision === 'CONTENT_DRAFT_READY') {
  return [{ json: contentResult }];
}

// Sourced from Resolve Anchor Product Type - the one shared place this
// gets derived now, instead of being recomputed separately here and in
// "Get Product Type Definition"'s URL. That duplication is exactly how
// this used to go stale in one spot and not the other.
const anchorProductType = $('Resolve Anchor Product Type').first().json.product_type || items[0].normalized_product_type || 'PRODUCT';

const schema = $('Fetch Schema').first().json;

// ============= Conditional requirement evaluator =============
// schema.required alone is only the FLAT, unconditional list. Amazon's real
// schemas also require fields conditionally via allOf/if/then/else blocks -
// e.g. batteries_required, which becomes mandatory whenever a payload has no
// fulfillment_availability, which every parent-only payload has by design
// (OFFER_MANAGED_ATTRS below excludes it deliberately). That gap is what let
// three separate new-parent submissions, across two product types, build a
// payload Amazon rejected outright - schema.required never mentioned the
// field that actually blocked them. This walks the real conditional
// structure instead of trusting the flat list alone.
//
// Supported operators: required, properties, allOf, anyOf, not, contains
// (true if at least one array element matches), items (true if every array
// element matches), enum, if/then/else. Anything else in a condition is
// treated as trivially true rather than thrown on - deliberately
// conservative, since a missed requirement here still gets caught by
// Amazon's own validation later (the exact problem before this existed),
// while a thrown exception would block every payload build outright.
function schemaMatches(condition, candidate) {
  if (!condition || typeof condition !== 'object') return true;

  if (Array.isArray(condition.required)) {
    for (const key of condition.required) {
      const val = candidate[key];
      if (val === undefined || val === null) return false;
      if (Array.isArray(val) && val.length === 0) return false;
    }
  }
  if (condition.properties) {
    for (const key of Object.keys(condition.properties)) {
      if (Object.prototype.hasOwnProperty.call(candidate, key)) {
        if (!schemaMatchesValue(condition.properties[key], candidate[key])) return false;
      }
    }
  }
  if (Array.isArray(condition.allOf)) {
    for (const sub of condition.allOf) {
      if (!schemaMatches(sub, candidate)) return false;
    }
  }
  if (Array.isArray(condition.anyOf)) {
    if (!condition.anyOf.some(function(sub) { return schemaMatches(sub, candidate); })) return false;
  }
  if (condition.not) {
    if (schemaMatches(condition.not, candidate)) return false;
  }
  return true;
}

function schemaMatchesValue(subschema, value) {
  if (!subschema || typeof subschema !== 'object') return true;
  if (Array.isArray(subschema.enum)) {
    if (subschema.enum.indexOf(value) === -1) return false;
  }
  if (subschema.contains) {
    if (!Array.isArray(value)) return false;
    if (!value.some(function(el) { return schemaMatches(subschema.contains, el); })) return false;
  }
  if (subschema.items) {
    if (!Array.isArray(value)) return false;
    if (!value.every(function(el) { return schemaMatches(subschema.items, el); })) return false;
  }
  if ((subschema.required || subschema.properties) && !subschema.contains && !subschema.items) {
    if (!value || typeof value !== 'object') return false;
    if (!schemaMatches(subschema, value)) return false;
  }
  return true;
}

// Walks one allOf-array entry - either a bare {if, then[, else]}, or a
// wrapper {allOf: [{if,then}, {if,then}]} (both shapes are real - color and
// model_number wrap two conditions this way; batteries_required is bare).
// Accumulates every then/else.required field that actually applies, plus
// which condition triggered it and whether via then or else, so a
// surprising result is debuggable rather than a black box - same instinct
// as wf15's theme_attribute_debug.
function collectRequired(entry, candidate, collected, trace, nestedRequired) {
  if (entry.if) {
    const isTrue = schemaMatches(entry.if, candidate);
    const branch = isTrue ? entry.then : entry.else;
    if (branch) applyBranch(branch, candidate, collected, trace, entry, isTrue, nestedRequired);
  } else if (Array.isArray(entry.allOf)) {
    entry.allOf.forEach(function(sub) { collectRequired(sub, candidate, collected, trace, nestedRequired); });
  } else if (Array.isArray(entry.required)) {
    entry.required.forEach(function(f) { collected.add(f); });
  }
}

function applyBranch(branch, candidate, collected, trace, sourceEntry, isTrue, nestedRequired) {
  if (Array.isArray(branch.required)) {
    branch.required.forEach(function(f) {
      if (!collected.has(f)) {
        trace[f] = { branch: isTrue ? 'then' : 'else', if_snippet: JSON.stringify(sourceEntry.if).slice(0, 300) };
      }
      collected.add(f);
    });
  }
  // Amazon expresses "X becomes required" a second way: not as a flat
  // top-level attribute, but as a FIELD WITHIN an existing structured
  // attribute's own array items - then.properties.<attr>.items.required
  // (or .required for a non-array attribute). This is exactly how
  // body_type/height_type become required once shirt_size carries
  // size_class/size_system - confirmed against the real SHIRT schema:
  // neither is a standalone attribute anywhere in it, only ever a sibling
  // field inside shirt_size's own entries. schemaMatches already evaluates
  // the surrounding if/then correctly; nothing previously read a
  // requirement nested this way, so it silently vanished even when the
  // condition was genuinely true - confirmed live: a real color-only
  // parent carrying an anchor's shirt_size (size_class 'alpha', age_range
  // 'Adult') satisfied this exact condition, and Amazon rejected the
  // submission for missing body_type/height_type that this workflow's own
  // evaluator never even flagged as required.
  if (branch.properties) {
    Object.keys(branch.properties).forEach(function(attrName) {
      const propSchema = branch.properties[attrName];
      const subReq = (propSchema && propSchema.items && Array.isArray(propSchema.items.required))
        ? propSchema.items.required
        : (propSchema && Array.isArray(propSchema.required) ? propSchema.required : null);
      if (subReq) {
        if (!nestedRequired[attrName]) nestedRequired[attrName] = new Set();
        subReq.forEach(function(f) { nestedRequired[attrName].add(f); });
      }
    });
  }
  if (Array.isArray(branch.allOf)) {
    branch.allOf.forEach(function(sub) { collectRequired(sub, candidate, collected, trace, nestedRequired); });
  }
  if (branch.if) {
    collectRequired(branch, candidate, collected, trace, nestedRequired);
  }
}

function evaluateRequiredAttributes(schemaArg, candidate) {
  const collected = new Set(Array.isArray(schemaArg.required) ? schemaArg.required : []);
  const trace = {};
  const nestedRequired = {};
  (Array.isArray(schemaArg.allOf) ? schemaArg.allOf : []).forEach(function(entry) {
    collectRequired(entry, candidate, collected, trace, nestedRequired);
  });
  const nestedRequiredPlain = {};
  Object.keys(nestedRequired).forEach(function(k) { nestedRequiredPlain[k] = Array.from(nestedRequired[k]); });
  return { required: Array.from(collected), trace: trace, nestedRequired: nestedRequiredPlain };
}

// Self-contained synthetic candidate for evaluation purposes only - built
// here from anchorItem.attributes directly, deliberately not sharing the
// real parentAttributes/themeName computed further below, so this whole
// section stays self-contained and nothing else in this function needs to
// move or change order. Tradeoff worth knowing: these four constants
// mirror THEME_MANAGED_ATTRS/CONTENT_MANAGED_ATTRS/dimensionAttrs/
// OFFER_MANAGED_ATTRS defined below - if those four are ever edited, this
// copy needs the same edit, since both describe the same real fact (which
// attributes never come from the anchor as-is on a parent record).
const EVAL_THEME_MANAGED = ['parentage_level', 'child_parent_sku_relationship', 'variation_theme'];
const EVAL_CONTENT_MANAGED = ['item_name', 'bullet_point', 'product_description'];
const EVAL_OFFER_MANAGED = ['merchant_shipping_group', 'fulfillment_availability', 'condition_type'];
const evalDimensionAttrs = [mergeRow.dimension1_attribute];
if (mergeRow.dimension2_attribute) evalDimensionAttrs.push(mergeRow.dimension2_attribute);
const evalThemeName = mergeRow.dimension2_theme
  ? mergeRow.dimension1_theme + '/' + mergeRow.dimension2_theme
  : mergeRow.dimension1_theme;

const evalCandidate = {
  parentage_level: [{ value: 'parent', marketplace_id: mkId }],
  variation_theme: [{ name: evalThemeName, marketplace_id: mkId }]
};
Object.keys(anchorItem.attributes || {}).forEach(function(attrName) {
  if (EVAL_THEME_MANAGED.indexOf(attrName) !== -1) return;
  if (EVAL_CONTENT_MANAGED.indexOf(attrName) !== -1) return;
  if (evalDimensionAttrs.indexOf(attrName) !== -1) return;
  if (EVAL_OFFER_MANAGED.indexOf(attrName) !== -1) return;
  const raw = anchorItem.attributes[attrName];
  if (Array.isArray(raw) && raw.length > 0) evalCandidate[attrName] = raw;
});

const requiredEval = evaluateRequiredAttributes(schema, evalCandidate);
const requiredAttrs = requiredEval.required;

// ============= Missing-requirement resolution (children, then a narrow,
// explicit default - never a guess) =============
// Reuses the same composite-key comparison approach that fixed the
// analogous problem in 26's uniqueness check - a structured value (or a
// simple one) compared correctly, not via naive String(v).
function normValue(v) {
  if (v === null || v === undefined) return null;
  if (typeof v === 'object') {
    const keys = Object.keys(v).filter(function(k) { return v[k] !== null && v[k] !== undefined; }).sort();
    if (keys.length === 0) return null;
    return keys.map(function(k) { return k + ':' + normValue(v[k]); }).join('|');
  }
  return String(v).trim().toLowerCase();
}

function getChildAttrValue(childListing, attrName) {
  if (!childListing || !childListing.attributes || !childListing.attributes[attrName]) return null;
  const entries = childListing.attributes[attrName];
  if (!Array.isArray(entries) || entries.length === 0) return null;
  const entry = entries.find(function(e) { return e.marketplace_id === mkId; }) || entries[0];
  if (!entry) return null;
  if (entry.value !== undefined) return entry.value;
  const structured = {};
  let hasFields = false;
  Object.keys(entry).forEach(function(k) {
    if (k === 'marketplace_id' || k === 'language_tag') return;
    structured[k] = entry[k];
    hasFields = true;
  });
  return hasFields ? structured : null;
}

// Explicit, narrow, human-reviewed per field - NOT a general "assume false"
// rule. One entry today, added for this project's current non-battery test
// catalog specifically. Revisit before relying on this for any product that
// might genuinely contain a battery.
const SAFE_DEFAULTS = {
  batteries_required: false
};

function resolveFromChildren(fieldName, childListings) {
  const values = [];
  childListings.forEach(function(c) {
    const v = getChildAttrValue(c, fieldName);
    if (v !== null) values.push({ raw: v, norm: normValue(v) });
  });
  if (values.length === 0) {
    if (Object.prototype.hasOwnProperty.call(SAFE_DEFAULTS, fieldName)) {
      return { resolved: true, value: SAFE_DEFAULTS[fieldName], source: 'safe_default_no_children_value' };
    }
    return { resolved: false, reason: 'no_value_anywhere' };
  }
  const distinctNorms = Array.from(new Set(values.map(function(v) { return v.norm; })));
  if (distinctNorms.length === 1) {
    return { resolved: true, value: values[0].raw, source: 'consistent_across_children' };
  }
  return { resolved: false, reason: 'children_disagree', observed_values: values.map(function(v) { return v.raw; }) };
}


if (requiredAttrs.length === 0) {
  return [{ json: {
    decision: 'REJECTED',
    reason: 'SCHEMA_REQUIRED_LIST_EMPTY',
    request_id: mergeRow.request_id,
    message: 'Amazon\'s schema for this product type returned no required-attribute list. Cannot safely build a parent payload without knowing what is mandatory.'
  }}];
}


// These get set explicitly below, not copied from the anchor's raw
// attributes, even though Amazon's own required list includes them.
const THEME_MANAGED_ATTRS = ['parentage_level', 'child_parent_sku_relationship', 'variation_theme'];
// Also set explicitly below - from the seller-confirmed generated
// content (contentResult, guaranteed CONTENT_CONFIRMED by this point,
// since the draft branch above already returned otherwise), never
// copied verbatim from the anchor. A real child's title/bullets/
// description name specific colors and sizes; a parent's can't.
const CONTENT_MANAGED_ATTRS = ['item_name', 'bullet_point', 'product_description'];

// Switched from "add" to "replace" for every patch here - two real,
// confirmed-working submissions found today both used "replace" for
// setting listing attributes via PATCH (Amazon's own migration
// tutorial, and a third-party guide with a confirmed ACCEPTED
// response), while every real submission this project has made so far
// used "add" exclusively and failed every time with a generic
// BAD_REQUEST. Not proven yet against a real call of our own - the
// attribute paths themselves are already confirmed valid (a separate
// real report showed "delete" succeeding on these same two attributes,
// parentage_level and child_parent_sku_relationship, for the reverse
// operation) - this is the one remaining common factor untested until now.
// Amazon's real theme-name format is already underscore/uppercase (COLOR,
// SIZE, ITEM_LENGTH, ...) straight from the live PTD API.
const themeName = mergeRow.dimension2_theme
  ? mergeRow.dimension1_theme + '/' + mergeRow.dimension2_theme
  : mergeRow.dimension1_theme;

const dimensionAttrs = [mergeRow.dimension1_attribute];
if (mergeRow.dimension2_attribute) dimensionAttrs.push(mergeRow.dimension2_attribute);

// Everything describing HOW a specific sellable unit is fulfilled or
// conditioned, not WHAT the product is - confirmed against RED-Small's
// real attribute set and SP-API's own semantics for each:
// merchant_shipping_group routes fulfillment for a specific unit,
// fulfillment_availability carries FBA/FBM designation and warehouse
// quantity (inventory-level by definition), condition_type describes a
// specific physical unit's condition. Structurally incompatible with a
// parent record, which explicitly isn't a sellable unit (see wf24's own
// comment on parents being non-buyable placeholder records).
// Deliberately Amazon-structural, not product-type content - shouldn't
// need to grow per product type, only if Amazon introduces a genuinely
// new offer-level concept.
const OFFER_MANAGED_ATTRS = ['merchant_shipping_group', 'fulfillment_availability', 'condition_type'];

// Copies every real attribute the anchor actually has, not just the
// schema-required subset - that's the actual fix. Driving this from
// schema.required alone meant any real, optional catalog content (an
// image, anything else not yet seen) silently never made it onto the
// parent - confirmed live on Parent_TQ34 and Parent_UX47 both.
// Required-ness is a separate check below now, not the thing deciding
// what gets copied at all.
const parentAttributes = {};

Object.keys(anchorItem.attributes || {}).forEach(function(attrName) {
  if (THEME_MANAGED_ATTRS.indexOf(attrName) !== -1) return;
  if (CONTENT_MANAGED_ATTRS.indexOf(attrName) !== -1) return;
  if (dimensionAttrs.indexOf(attrName) !== -1) return;
  if (OFFER_MANAGED_ATTRS.indexOf(attrName) !== -1) return;

  const raw = anchorItem.attributes[attrName];
  if (!Array.isArray(raw) || raw.length === 0) return;
  const entry = raw.find(function(e) { return e.marketplace_id === mkId; }) || raw[0];
  parentAttributes[attrName] = [entry];
});

// Same hard stop as before if something truly mandatory is missing -
// checked against what actually landed in parentAttributes now, since
// required-ness is no longer the sole gate on what's copied. All four
// exclusion categories are excluded here too, for the same reason they
// were excluded from the copy loop above - an offer-managed attribute
// that happened to also be schema-required should never be miscounted
// as "missing," since it was never meant to be copied in the first
// place.
const missingFromAnchor = requiredAttrs.filter(function(attrName) {
  if (THEME_MANAGED_ATTRS.indexOf(attrName) !== -1) return false;
  if (CONTENT_MANAGED_ATTRS.indexOf(attrName) !== -1) return false;
  if (dimensionAttrs.indexOf(attrName) !== -1) return false;
  if (OFFER_MANAGED_ATTRS.indexOf(attrName) !== -1) return false;
  return !parentAttributes[attrName];
});

// Anything the anchor is missing gets one more chance before rejecting:
// check whether the children can answer it instead. childListingsRaw comes
// from the new Fetch Child Listings node - real Amazon attributes per
// child, which did not exist anywhere in this workflow before.
const childListingsRaw = $('Fetch Child Listings').all().map(function(i) { return i.json; });
const stillMissing = [];
const resolutionTrace = {};
missingFromAnchor.forEach(function(attrName) {
  const result = resolveFromChildren(attrName, childListingsRaw);
  if (result.resolved) {
    parentAttributes[attrName] = [{ value: result.value, marketplace_id: mkId }];
    resolutionTrace[attrName] = { resolved: true, source: result.source };
  } else {
    stillMissing.push(attrName);
    resolutionTrace[attrName] = Object.assign({ resolved: false }, result);
  }
});

const droppedForUnrelatedRequirements = [];
if (stillMissing.length > 0) {
  // Each of these became required only because SOME attribute got carried
  // over from the anchor's own full attribute set and pulled in a schema
  // condition unrelated to this merge's actual theme - not because it's
  // unconditionally mandatory for every parent of this product type.
  // Confirmed live: a real SHIRT anchor's own pre-existing shirt_size,
  // carried onto a COLOR-only parent by the copy loop above, triggered
  // Amazon's body_type/height_type requirement - fields nobody involved in
  // a color merge was ever asked for, and neither the anchor nor its
  // sibling children had real values for. Rather than reject a merge that
  // has nothing to do with sizing, check whether dropping one of the
  // anchor's own optional (non-theme, non-managed) attributes removes the
  // requirement entirely. If so, that attribute - not this merge - was the
  // actual cause, and it's left off the parent rather than sent to Amazon
  // or used to block a request it was never relevant to. This only
  // changes the outcome when dropping an attribute genuinely clears a
  // requirement; anything still missing afterward is rejected exactly as
  // before, with the same message.
  const optionalCopiedAttrs = Object.keys(parentAttributes).filter(function(attrName) {
    return THEME_MANAGED_ATTRS.indexOf(attrName) === -1
      && CONTENT_MANAGED_ATTRS.indexOf(attrName) === -1
      && dimensionAttrs.indexOf(attrName) === -1
      && OFFER_MANAGED_ATTRS.indexOf(attrName) === -1;
  });

  let remainingMissing = stillMissing.slice();

  optionalCopiedAttrs.forEach(function(candidateToDrop) {
    if (remainingMissing.length === 0) return;
    const probe = Object.assign({}, evalCandidate);
    delete probe[candidateToDrop];
    const probeRequired = {};
    evaluateRequiredAttributes(schema, probe).required.forEach(function(f) { probeRequired[f] = true; });
    const cleared = remainingMissing.filter(function(f) { return !probeRequired[f]; });
    if (cleared.length > 0) {
      delete parentAttributes[candidateToDrop];
      droppedForUnrelatedRequirements.push({ attribute: candidateToDrop, resolved_missing: cleared });
      remainingMissing = remainingMissing.filter(function(f) { return probeRequired[f]; });
    }
  });

  if (remainingMissing.length > 0) {
    const missingTrace = {};
    remainingMissing.forEach(function(attrName) {
      missingTrace[attrName] = Object.assign(
        { required_because: requiredEval.trace[attrName] || { branch: 'flat_schema_required', if_snippet: null } },
        resolutionTrace[attrName]
      );
    });
    return [{ json: {
      decision: 'REJECTED',
      reason: 'ANCHOR_MISSING_REQUIRED_ATTRIBUTES',
      request_id: mergeRow.request_id,
      message: 'The anchor listing itself is missing a real value for ' + remainingMissing.join(', ') + ' - Amazon requires this for this product type, parent or not, and there is no honest way to fill it in without one.',
      missing_attributes: remainingMissing,
      missing_attributes_trace: missingTrace,
      dropped_unrelated_attributes: droppedForUnrelatedRequirements
    }}];
  }
  // Everything that was missing got resolved by dropping the anchor
  // attribute(s) that pulled it in - fall through and keep building the
  // payload, just without those specific attributes on the parent.
}

// A second, independent pass for requirements nested inside a structured
// attribute's own items (see evaluateRequiredAttributes/applyBranch above -
// e.g. shirt_size needing body_type/height_type once populated with
// size_class/size_system). These were silently invisible to every check
// above, since they were never top-level attribute names to begin with -
// Amazon's schema never defines body_type or height_type as standalone
// attributes anywhere, only ever as sibling fields inside shirt_size's own
// array entries. Resolved the same way as the flat case: check the
// children's own real data for the missing sub-field first: if every
// child that has this attribute agrees on a real value, merge it in. If
// there's genuinely nothing to go on, drop the whole attribute rather than
// send Amazon a structured value it will reject as incomplete.
Object.keys(requiredEval.nestedRequired || {}).forEach(function(attrName) {
  if (!parentAttributes[attrName]) return; // never made it onto the parent - nothing to check
  const requiredSubFields = requiredEval.nestedRequired[attrName];
  const currentEntry = parentAttributes[attrName][0] || {};
  const missingSubFields = requiredSubFields.filter(function(sf) {
    return currentEntry[sf] === undefined || currentEntry[sf] === null;
  });
  if (missingSubFields.length === 0) return; // already complete

  const resolvedSubFields = {};
  const unresolvedSubFields = [];
  missingSubFields.forEach(function(sf) {
    const found = [];
    childListingsRaw.forEach(function(c) {
      const structured = getChildAttrValue(c, attrName);
      if (structured && typeof structured === 'object' && structured[sf] !== undefined && structured[sf] !== null) {
        found.push(structured[sf]);
      }
    });
    const distinctNorms = Array.from(new Set(found.map(normValue)));
    if (distinctNorms.length === 1 && found.length > 0) {
      resolvedSubFields[sf] = found[0];
    } else {
      unresolvedSubFields.push(sf);
    }
  });

  if (unresolvedSubFields.length > 0) {
    delete parentAttributes[attrName];
    droppedForUnrelatedRequirements.push({
      attribute: attrName,
      resolved_missing: unresolvedSubFields.map(function(sf) { return attrName + '.' + sf; })
    });
  } else {
    parentAttributes[attrName] = [Object.assign({}, currentEntry, resolvedSubFields)];
  }
});

// Confirmed content fills in exactly the content-managed attributes this
// product type actually requires, and none it doesn't - some product
// types don't require bullet_point at all, for instance.
// language_tag included on all three - confirmed against this same
// payload's own real, anchor-sourced fields (brand, fabric_type both
// carry it; the enum-like fields like country_of_origin and color_name
// don't). These three are free text the same way brand/fabric_type are,
// so they get the same treatment rather than an inconsistent guess.
if (requiredAttrs.indexOf('item_name') !== -1) {
  parentAttributes.item_name = [{ value: contentResult.title, language_tag: 'en_US', marketplace_id: mkId }];
}
if (requiredAttrs.indexOf('bullet_point') !== -1) {
  parentAttributes.bullet_point = (contentResult.bullet_points || []).map(function(b) {
    return { value: b, language_tag: 'en_US', marketplace_id: mkId };
  });
}
if (requiredAttrs.indexOf('product_description') !== -1) {
  parentAttributes.product_description = [{ value: contentResult.description, language_tag: 'en_US', marketplace_id: mkId }];
}

// The parent record itself: brand-new SKU, no price/inventory/images -
// just the identity fields Amazon requires, sourced from the real listing
// being promoted, plus whatever else this specific product type requires.
parentAttributes.parentage_level = [{ value: 'parent', marketplace_id: mkId }];
parentAttributes.variation_theme = [{ name: themeName, marketplace_id: mkId }];

const parentPatches = Object.keys(parentAttributes).map(function(attrName) {
  return { op: 'replace', path: '/attributes/' + attrName, value: parentAttributes[attrName] };
});

const parentListing = {
  messageId: 1,
  sku: mergeRow.new_parent_sku,
  operationType: 'PATCH',
  productType: anchorProductType,
  patches: parentPatches
};

// The anchor becomes a full child too - same shape as every other child,
// just sourced from a captured value on the merge_requests row instead of
// a merge_request_items row, since it was never "added" the way the others
// were - it's the listing the whole promotion started from.
// Builds the correctly-shaped array value for an attribute PATCH, given a
// raw value that might be simple (a string/number) or structured (an
// object with its own sub-fields, e.g. footwear_size/shirt_size).
// Structured attributes have no "value" property in their real schema at
// all - size/size_class/size_system etc. sit as direct sibling fields on
// the entry - wrapping one in {value: ...} is exactly what got a real
// FG92 submission rejected by Amazon. Mirrors how parentAttributes
// already handles this correctly when copying straight from the anchor's
// own attributes.
function buildAttributeEntry(rawValue, marketplaceId) {
  if (rawValue !== null && typeof rawValue === 'object' && !Array.isArray(rawValue)) {
    return [Object.assign({}, rawValue, { marketplace_id: marketplaceId })];
  }
  return [{ value: rawValue, marketplace_id: marketplaceId }];
}

const anchorOwnValues = mergeRow.anchor_own_values || {};
const anchorPatches = [
  { op: 'replace', path: '/attributes/parentage_level', value: [{ value: 'child', marketplace_id: mkId }] },
  { op: 'replace', path: '/attributes/child_parent_sku_relationship', value: [{ child_relationship_type: 'variation', parent_sku: mergeRow.new_parent_sku, marketplace_id: mkId }] },
  { op: 'replace', path: '/attributes/variation_theme', value: [{ name: themeName, marketplace_id: mkId }] },
  { op: 'replace', path: '/attributes/' + mergeRow.dimension1_attribute, value: buildAttributeEntry(anchorOwnValues[mergeRow.dimension1_attribute], mkId) }
];
if (mergeRow.dimension2_attribute && anchorOwnValues[mergeRow.dimension2_attribute]) {
  anchorPatches.push({ op: 'replace', path: '/attributes/' + mergeRow.dimension2_attribute, value: buildAttributeEntry(anchorOwnValues[mergeRow.dimension2_attribute], mkId) });
}

const anchorListing = {
  messageId: 2,
  sku: mergeRow.anchor_sku,
  operationType: 'PATCH',
  productType: anchorProductType,
  patches: anchorPatches
};

// The rest of the children - identical shape to the existing-parent flow,
// just referencing the newly-minted parent SKU instead of an existing one.
// Verified against the real, current JSON_LISTINGS_FEED v2 schema
// (amzn/selling-partner-api-models, schemas/feeds/listings-feed-schema-v2.json)
// before this was ever wired to a real submission trigger. No "body"
// wrapper exists in the real schema - messages sit directly under
// header, each with its own operationType and a required, submission-
// unique messageId. parentListing/anchorListing already got theirs
// above (1 and 2); the rest continue from 3.
const childListings = items.map(function(item, index) {
  const patches = [
    { op: 'replace', path: '/attributes/parentage_level', value: [{ value: 'child', marketplace_id: mkId }] },
    { op: 'replace', path: '/attributes/child_parent_sku_relationship', value: [{ child_relationship_type: 'variation', parent_sku: item.parent_sku, marketplace_id: mkId }] },
    { op: 'replace', path: '/attributes/variation_theme', value: [{ name: themeName, marketplace_id: mkId }] },
    { op: 'replace', path: '/attributes/' + mergeRow.dimension1_attribute, value: buildAttributeEntry(item.dimension1_value, mkId) }
  ];
  if (mergeRow.dimension2_attribute && item.dimension2_value) {
    patches.push({ op: 'replace', path: '/attributes/' + mergeRow.dimension2_attribute, value: buildAttributeEntry(item.dimension2_value, mkId) });
  }
  return {
    messageId: index + 3,
    sku: item.sku,
    operationType: 'PATCH',
    productType: item.normalized_product_type || 'PRODUCT',
    patches: patches
  };
});

const jsonPayload = {
  header: { sellerId: mergeRow.seller_id, version: '2.0', issueLocale: 'en_US' },
  messages: [parentListing, anchorListing].concat(childListings)
};

return [{ json: {
  decision: 'PAYLOAD_READY',
  request_id: mergeRow.request_id,
  new_parent_sku: mergeRow.new_parent_sku,
  anchor_sku: mergeRow.anchor_sku,
  child_count: childListings.length + 1,
  content_source: contentResult.generated === false ? 'seller_confirmed' : 'seller_confirmed_after_review',
  parent_attributes_sourced_from_anchor: Object.keys(parentAttributes).filter(function(k) { return THEME_MANAGED_ATTRS.indexOf(k) === -1; }),
  dropped_unrelated_attributes: droppedForUnrelatedRequirements,
  required_attributes_evaluated: requiredAttrs,
  required_attributes_trace: requiredEval.trace,
  resolved_from_children: resolutionTrace,
  json_payload: jsonPayload
}}];

const mergeRaw = $('Fetch Merge Request').first().json;
const mergeRow = Array.isArray(mergeRaw) ? mergeRaw[0] : mergeRaw;
const anchorItem = $('Fetch Anchor Listing').first().json;
const validateInput = $('Validate Input').first().json;

const itemsInput = $('Fetch Items').all();
let items;
if (itemsInput.length === 1 && Array.isArray(itemsInput[0].json)) {
  items = itemsInput[0].json;
} else {
  items = itemsInput.map(function(i) { return i.json; });
}

// If the seller already reviewed (and possibly edited) this content on a
// prior call to this same webhook, use exactly what they confirmed -
// never silently regenerate over a real edit.
if (validateInput.confirmed_title || validateInput.confirmed_bullet_points || validateInput.confirmed_description) {
  return [{ json: {
    decision: 'CONTENT_CONFIRMED',
    title: validateInput.confirmed_title || null,
    bullet_points: Array.isArray(validateInput.confirmed_bullet_points) ? validateInput.confirmed_bullet_points : [],
    description: validateInput.confirmed_description || null,
    generated: false
  }}];
}

function forMarketplace(list, mkId) {
  if (!Array.isArray(list)) return {};
  return list.find(function(e) { return e.marketplaceId === mkId; }) || list[0] || {};
}
const mkId = mergeRow.marketplace_id;
const anchorSummary = forMarketplace(anchorItem.summaries, mkId);

function attrValue(attrName) {
  const raw = anchorItem.attributes ? anchorItem.attributes[attrName] : undefined;
  if (!raw || !Array.isArray(raw) || raw.length === 0) return null;
  const entry = raw.find(function(e) { return e.marketplace_id === mkId; }) || raw[0];
  return entry ? entry.value : null;
}
function attrValues(attrName) {
  const raw = anchorItem.attributes ? anchorItem.attributes[attrName] : undefined;
  if (!Array.isArray(raw)) return [];
  return raw
    .filter(function(e) { return !e.marketplace_id || e.marketplace_id === mkId; })
    .map(function(e) { return e.value; })
    .filter(Boolean);
}

const rawTitle = anchorSummary.itemName || attrValue('item_name') || '';
const rawBullets = attrValues('bullet_point');
const rawDescription = attrValue('product_description') || '';

// Every real variant value across the whole family - the anchor's own
// (captured on the merge_requests row back in Child Entry) plus every
// other child's. A generic parent title can't keep any of these, not
// just the anchor's own value.
const anchorOwnValues = mergeRow.anchor_own_values || {};
const variantTokens = [];
[mergeRow.dimension1_attribute, mergeRow.dimension2_attribute].forEach(function(attr) {
  if (!attr) return;
  if (anchorOwnValues[attr]) variantTokens.push(anchorOwnValues[attr]);
  const key = attr === mergeRow.dimension1_attribute ? 'dimension1_value' : 'dimension2_value';
  items.forEach(function(item) {
    if (item[key]) variantTokens.push(item[key]);
  });
});

// Common size abbreviations sellers use in titles alongside (or instead
// of) the full value - added whenever the corresponding full value is a
// real token here, so "M" is still caught even when the stored/entered
// value is "Medium".
const ABBREVIATIONS = {
  'extra small': 'XS', 'small': 'S', 'medium': 'M', 'large': 'L',
  'extra large': 'XL', 'extra extra large': 'XXL', 'x-large': 'XL', 'xx-large': 'XXL'
};
const expandedTokens = [];
variantTokens.forEach(function(t) {
  expandedTokens.push(t);
  const abbr = ABBREVIATIONS[String(t).toLowerCase()];
  if (abbr) expandedTokens.push(abbr);
});
// Longest first, so "Extra Large" is removed whole before "Large" could
// match inside it and leave a stray "Extra ".
const uniqueTokens = Array.from(new Set(expandedTokens)).sort(function(a, b) { return b.length - a.length; });

// Case-sensitive on purpose: these tokens are Amazon attribute values as
// the seller actually entered them (Child Entry stores them Title Case,
// matching how Amazon's own PTD enums and real titles use them), and
// staying case-sensitive means a common lowercase word that happens to
// match one - "green" in "eco-friendly green initiative" - is left
// alone rather than stripped as if it were the color attribute.
function removeTokens(text) {
  if (!text) return text;
  let out = text;
  uniqueTokens.forEach(function(token) {
    const escaped = String(token).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    out = out.replace(new RegExp('\\b' + escaped + '\\b', 'g'), '');
  });
  return out;
}

function finalCleanup(text) {
  return text
    .replace(/\(\s*\)/g, '')
    .replace(/\[\s*\]/g, '')
    .replace(/\s*,\s*,/g, ',')
    .replace(/,\s*$/, '')
    .replace(/^\s*,\s*/, '')
    .replace(/\s{2,}/g, ' ')
    .trim();
}

const LABEL_WORDS = ['size', 'colour', 'color', 'flavour', 'flavor', 'style', 'scent', 'material'];

// Titles are usually segmented ("Base Name - Attr1 - Attr2" or
// "Base Name, Attr1, Attr2"): split on the common separators, drop any
// segment that's now empty or is nothing but a bare label word once
// tokens are removed, rejoin what's left with a consistent " - ".
function stripTitleVariants(text) {
  if (!text) return text;
  const segments = text.split(/\s*[-|,\u2013\u2014]\s*/);
  const kept = segments
    .map(function(seg) { return finalCleanup(removeTokens(seg)); })
    .filter(function(seg) {
      if (!seg) return false;
      const bare = seg.toLowerCase().replace(/[:()]/g, '').trim();
      return LABEL_WORDS.indexOf(bare) === -1;
    });
  return kept.join(' - ');
}

// Bullets/description are full sentences, not segmented fields - only
// remove the tokens themselves, never a label word. A label word is
// virtually always a real, meaningful word in running prose ("adds a
// pop of color", "style meets comfort") - stripping it there breaks the
// sentence rather than genericizing it, confirmed by testing this
// against realistic examples before this shipped.
function stripProseVariants(text) {
  if (!text) return text;
  return finalCleanup(removeTokens(text));
}

const draftTitle = stripTitleVariants(rawTitle);
const draftBullets = rawBullets.map(stripProseVariants).filter(Boolean);
const draftDescription = stripProseVariants(rawDescription);

return [{ json: {
  decision: 'CONTENT_DRAFT_READY',
  request_id: mergeRow.request_id,
  title: draftTitle,
  bullet_points: draftBullets,
  description: draftDescription,
  generated: true,
  source_title: rawTitle,
  source_bullet_points: rawBullets,
  source_description: rawDescription,
  variant_tokens_stripped: uniqueTokens
}}];

const mergeRaw = $('Fetch Merge Request').first().json;
const mergeRow = Array.isArray(mergeRaw) ? mergeRaw[0] : mergeRaw;
const anchorItem = $('Fetch Anchor Listing').first().json;

// productType does NOT come back as a bare top-level field on the
// Listings Items response - confirmed against wf19's own tested parsing
// of this identical endpoint. It lives on the marketplace-matched entry
// inside summaries[], same place item_name/asin/status live.
//
// This used to be computed inline, separately, in both this workflow's
// "Get Product Type Definition" URL AND in Build Payload - both wrong
// the same way (reading anchorItem.productType directly, always
// undefined), because there was no single shared place either one
// pulled it from. That's the actual root cause, not just the missing
// nesting: fixing it in one spot and not the other is exactly what
// happened the first time. Now there's one place, referenced by both.
function forMarketplace(list) {
  if (!Array.isArray(list)) return {};
  return list.find(function(e) { return e.marketplaceId === mergeRow.marketplace_id; }) || list[0] || {};
}
const anchorSummary = forMarketplace(anchorItem.summaries);

return [{ json: {
  product_type: anchorSummary.productType || null
}}];

// Fetches each child's real Amazon attributes - this did not exist before.
// The only prior per-item data was Fetch Items' Supabase row (sku, asin,
// parent_sku, dimension1_value, dimension2_value, normalized_product_type),
// which has no real Amazon attribute data at all. Needed so a conditionally
// required attribute the anchor lacks (e.g. batteries_required) can be
// resolved from the children instead of just failing outright. Same
// endpoint, same includedData, same auth pattern as Fetch Anchor Listing -
// just parameterized per child SKU instead of the anchor's.
return (async function() {
  const itemsInput = $('Fetch Items').all();
  const items = (itemsInput.length === 1 && Array.isArray(itemsInput[0].json))
    ? itemsInput[0].json
    : itemsInput.map(function(i) { return i.json; });

  const accessToken = $('Exchange for Access Token').first().json.access_token;
  const sellingPartnerId = $('Get Seller Selling Partner ID').first().json.selling_partner_id;
  const marketplaceId = $('Fetch Merge Request').first().json.marketplace_id;

  const results = [];
  for (const item of items) {
    try {
      const response = await this.helpers.httpRequest({
        method: 'GET',
        url: 'https://sellingpartnerapi-na.amazon.com/listings/2021-08-01/items/' + sellingPartnerId
          + '/' + encodeURIComponent(item.sku)
          + '?marketplaceIds=' + marketplaceId + '&includedData=summaries,attributes',
        headers: { 'x-amz-access-token': accessToken },
        json: true
      });
      results.push({ sku: item.sku, attributes: (response && response.attributes) || {}, fetch_error: null });
    } catch (err) {
      // A single child's fetch failing shouldn't block the whole payload
      // build - it just means this child can't help resolve a missing
      // attribute, same as if it genuinely had none. Recorded, not thrown.
      results.push({ sku: item.sku, attributes: {}, fetch_error: (err && err.message) || 'unknown error' });
    }
  }
  return results.map(function(r) { return { json: r }; });
}).call(this);
